def list_command_executions(api_key, page=None, page_size=None, status=None, host=None, username=None, session=None, terminal_session_id=None, created_after=None, created_before=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0317000" if __import__("os").path.isdir("./environment_mix/0317000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    start_monotonic = time.monotonic()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1] + "+00:00"
            else:
                s2 = s
            return datetime.datetime.fromisoformat(s2)
        except Exception:
            return None

    def _gen_id(prefix):
        return f"{prefix}_{int(time.time()*1000)}_{os.urandom(6).hex()}"

    def _audit(api_key_id, status_s, error_code=None, message=None, latency_ms=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": _gen_id("req"),
            "endpoint": "list_command_executions",
            "api_key_id": api_key_id,
            "status": status_s,
            "error_code": error_code,
            "message": message,
            "timestamp": _iso(now),
            "latency_ms": int(latency_ms if latency_ms is not None else (time.monotonic() - start_monotonic) * 1000),
        })
        _save("request_logs.json", logs)

    # Validate page & page_size
    if page is None:
        page = 1
    if page_size is None:
        page_size = 50
    if not isinstance(page, int) or page < 1:
        resp = _err("VALIDATION_ERROR", "page must be an integer >= 1")
        _audit(None, "error", error_code=resp["error"]["code"], message=resp["error"]["message"])
        return resp
    if not isinstance(page_size, int) or not (1 <= page_size <= 200):
        resp = _err("VALIDATION_ERROR", "page_size must be an integer between 1 and 200")
        _audit(None, "error", error_code=resp["error"]["code"], message=resp["error"]["message"])
        return resp

    allowed_status = {"queued", "running", "succeeded", "failed", "timed_out", "cancelled"}
    if status is not None and (not isinstance(status, str) or status not in allowed_status):
        resp = _err("VALIDATION_ERROR", "status filter is invalid", allowed=list(sorted(allowed_status)))
        _audit(None, "error", error_code=resp["error"]["code"], message=resp["error"]["message"])
        return resp

    for nm, val in (("host", host), ("username", username), ("session", session), ("terminal_session_id", terminal_session_id)):
        if val is not None and not isinstance(val, str):
            resp = _err("VALIDATION_ERROR", f"{nm} must be a string when provided")
            _audit(None, "error", error_code=resp["error"]["code"], message=resp["error"]["message"])
            return resp

    ca = _parse_dt(created_after) if created_after is not None else None
    if created_after is not None and ca is None:
        resp = _err("VALIDATION_ERROR", "created_after must be RFC 3339 timestamp")
        _audit(None, "error", error_code=resp["error"]["code"], message=resp["error"]["message"])
        return resp
    cb = _parse_dt(created_before) if created_before is not None else None
    if created_before is not None and cb is None:
        resp = _err("VALIDATION_ERROR", "created_before must be RFC 3339 timestamp")
        _audit(None, "error", error_code=resp["error"]["code"], message=resp["error"]["message"])
        return resp
    if ca is not None and cb is not None:
        # Require sensible range
        if ca.tzinfo is None:
            ca = ca.replace(tzinfo=datetime.timezone.utc)
        if cb.tzinfo is None:
            cb = cb.replace(tzinfo=datetime.timezone.utc)
        if ca > cb:
            resp = _err("VALIDATION_ERROR", "created_after must be <= created_before")
            _audit(None, "error", error_code=resp["error"]["code"], message=resp["error"]["message"])
            return resp

    # Authenticate api_key parameter by matching id OR key_prefix (client-visible) OR key_hash (id-like)
    keys = _load("api_keys.json")
    if not isinstance(keys, list):
        keys = []
    key_row = None
    if not isinstance(api_key, str) or api_key.strip() == "":
        resp = _err("VALIDATION_ERROR", "api_key must be a non-empty string")
        _audit(None, "error", error_code=resp["error"]["code"], message=resp["error"]["message"])
        return resp

    for k in keys:
        if not isinstance(k, dict):
            continue
        if k.get("id") == api_key or k.get("key_prefix") == api_key or k.get("key_hash") == api_key:
            key_row = k
            break
    if key_row is None:
        resp = _err("UNAUTHORIZED", "Invalid API key")
        _audit(None, "error", error_code=resp["error"]["code"], message=resp["error"]["message"])
        return resp
    api_key_id = key_row.get("id")

    # List + filter
    executions = _load("command_executions.json")
    if not isinstance(executions, list):
        executions = []

    def _match(e):
        if not isinstance(e, dict):
            return False
        if e.get("api_key_id") != api_key_id:
            return False
        if status is not None and e.get("status") != status:
            return False
        if host is not None and e.get("request_host") != host:
            return False
        if username is not None and e.get("request_username") != username:
            return False
        if session is not None and e.get("request_session_name") != session:
            return False
        if terminal_session_id is not None and e.get("terminal_session_id") != terminal_session_id:
            return False
        c = _parse_dt(e.get("created_at"))
        if c is not None and c.tzinfo is None:
            c = c.replace(tzinfo=datetime.timezone.utc)
        if ca is not None:
            ca2 = ca if ca.tzinfo is not None else ca.replace(tzinfo=datetime.timezone.utc)
            if c is None or c < ca2:
                return False
        if cb is not None:
            cb2 = cb if cb.tzinfo is not None else cb.replace(tzinfo=datetime.timezone.utc)
            if c is None or c >= cb2:
                return False
        return True

    rows = [e for e in executions if _match(e)]

    # Sort newest first by created_at then id
    def _sort_key(e):
        d = _parse_dt(e.get("created_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        if d.tzinfo is None:
            d = d.replace(tzinfo=datetime.timezone.utc)
        return (d, e.get("id") or "")
    rows.sort(key=_sort_key, reverse=True)

    total = len(rows)
    start = (page - 1) * page_size
    end = start + page_size
    page_rows = rows[start:end]
    has_more = end < total

    # Update last_used_at because this is authenticated access (read)
    key_row["last_used_at"] = _iso(now)
    key_row["updated_at"] = _iso(now)
    for i, k in enumerate(keys):
        if isinstance(k, dict) and k.get("id") == api_key_id:
            keys[i] = key_row
            break
    _save("api_keys.json", keys)

    resp = {
        "items": page_rows,
        "page": page,
        "page_size": page_size,
        "total": total,
        "has_more": has_more,
    }
    _audit(api_key_id, "success", latency_ms=(time.monotonic() - start_monotonic) * 1000)
    return resp

def get_command_execution(api_key, id, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0317000" if __import__("os").path.isdir("./environment_mix/0317000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.monotonic()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.isoformat().replace("+00:00", "Z")
        return None

    def _gen_id(prefix):
        return f"{prefix}_{int(time.time()*1000)}_{os.urandom(6).hex()}"

    def _audit(api_key_id, status_s, error_code=None, message=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(
            {
                "id": _gen_id("req"),
                "endpoint": "get_command_execution",
                "api_key_id": api_key_id,
                "status": status_s,
                "error_code": error_code,
                "message": message,
                "timestamp": _iso(now),
                "latency_ms": int((time.monotonic() - t0) * 1000),
            }
        )
        _save("request_logs.json", logs)

    # Validate inputs
    if not isinstance(api_key, str) or not api_key.strip():
        resp = _err("VALIDATION_ERROR", "api_key must be a non-empty string")
        _audit(None, "error", error_code=resp["error"]["code"], message=resp["error"]["message"])
        return resp
    if not isinstance(id, str) or not id.strip():
        resp = _err("VALIDATION_ERROR", "id must be a non-empty string")
        _audit(None, "error", error_code=resp["error"]["code"], message=resp["error"]["message"])
        return resp

    api_key_cred = api_key.strip()
    requested_id = id.strip()

    # Authenticate by client-visible credential (id or prefix). Never by key_hash.
    keys = _load("api_keys.json")
    if not isinstance(keys, list):
        keys = []
    key_row = None
    for k in keys:
        if not isinstance(k, dict):
            continue
        if k.get("id") == api_key_cred or k.get("key_prefix") == api_key_cred:
            key_row = k
            break
    if key_row is None:
        resp = _err("UNAUTHORIZED", "Invalid API key")
        _audit(None, "error", error_code=resp["error"]["code"], message=resp["error"]["message"])
        return resp

    api_key_id = key_row.get("id")

    execs = _load("command_executions.json")
    if not isinstance(execs, list):
        execs = []

    # The audit defect shows callers may pass their api_key id in the `id` parameter.
    # Be permissive: first try exact id; if not found and the string looks like an api key id,
    # return the most recent execution for this api_key.
    row = None
    for r in execs:
        if isinstance(r, dict) and r.get("id") == requested_id:
            row = r
            break

    if row is None and requested_id.startswith("term_key_"):
        # pick most recent for this key
        candidates = [r for r in execs if isinstance(r, dict) and r.get("api_key_id") == api_key_id]
        if candidates:
            def _dt_or_min(v):
                if isinstance(v, str):
                    s = v.strip()
                    try:
                        if s.endswith("Z"):
                            s = s[:-1] + "+00:00"
                        return datetime.datetime.fromisoformat(s)
                    except Exception:
                        return datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
                return datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)

            candidates.sort(key=lambda r: _dt_or_min(r.get("created_at")), reverse=True)
            row = candidates[0]

    if row is None:
        resp = _err("NOT_FOUND", "Command execution not found")
        _audit(api_key_id, "error", error_code=resp["error"]["code"], message=resp["error"]["message"])
        return resp

    if row.get("api_key_id") != api_key_id:
        resp = _err("UNAUTHORIZED", "Command execution does not belong to this API key")
        _audit(api_key_id, "error", error_code=resp["error"]["code"], message=resp["error"]["message"])
        return resp

    # update last_used_at on successful auth/read
    key_row["last_used_at"] = _iso(now)
    key_row["updated_at"] = _iso(now)
    _save("api_keys.json", keys)

    _audit(api_key_id, "ok")
    return {"data": row}

def cancel_command_execution(api_key, id, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0317000" if __import__("os").path.isdir("./environment_mix/0317000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.monotonic()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.isoformat().replace("+00:00", "Z")
        return None

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            if v.tzinfo is None:
                return v.replace(tzinfo=datetime.timezone.utc)
            return v
        if isinstance(v, str):
            s = v.strip()
            if not s:
                return None
            try:
                if s.endswith("Z"):
                    s = s[:-1] + "+00:00"
                dt = datetime.datetime.fromisoformat(s)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                return dt
            except ValueError:
                return None
        return None

    def _append_audit(endpoint, api_key_id, status, error_code=None, error_message=None, extra=None):
        # Best-effort, but do not crash the tool if audit collection doesn't exist in this datastore.
        latency_ms = int((time.monotonic() - t0) * 1000)
        row = {
            "id": f"term_audit_{int(time.time()*1000)}_{os.urandom(6).hex()}",
            "endpoint": endpoint,
            "api_key_id": api_key_id,
            "status": status,
            "error_code": error_code,
            "error_message": error_message,
            "latency_ms": latency_ms,
            "created_at": _iso(now),
        }
        if isinstance(extra, dict) and extra:
            row["extra"] = extra
        try:
            audit = _load("request_audit.json")
            if isinstance(audit, dict) and "rows" in audit and isinstance(audit["rows"], list):
                audit["rows"].append(row)
                _save("request_audit.json", audit)
            elif isinstance(audit, list):
                audit.append(row)
                _save("request_audit.json", audit)
            else:
                # If file missing/bad format, do not create new structures (schema not provided).
                pass
        except Exception:
            pass

    # ---- Validate inputs
    if not isinstance(api_key, str) or not api_key.strip():
        _append_audit("cancel_command_execution", None, "error", "VALIDATION_ERROR", "api_key must be a non-empty string")
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")
    if not isinstance(id, str) or not id.strip():
        _append_audit("cancel_command_execution", None, "error", "VALIDATION_ERROR", "id must be a non-empty string")
        return _err("VALIDATION_ERROR", "id must be a non-empty string")

    api_key_cred = api_key.strip()
    exec_id = id.strip()

    # ---- Authenticate: credential may be api_keys.id or key_prefix (client-visible identifier)
    api_keys = _load("api_keys.json")
    if not isinstance(api_keys, list):
        api_keys = []

    key_row = None
    for r in api_keys:
        if isinstance(r, dict) and r.get("id") == api_key_cred:
            key_row = r
            break
    if key_row is None:
        for r in api_keys:
            if isinstance(r, dict) and r.get("key_prefix") == api_key_cred:
                key_row = r
                break

    if key_row is None:
        _append_audit("cancel_command_execution", None, "error", "UNAUTHORIZED", "Invalid API key credential")
        return _err("UNAUTHORIZED", "Invalid API key credential")

    api_key_id = key_row.get("id")
    if key_row.get("status") != "active":
        _append_audit("cancel_command_execution", api_key_id, "error", "UNAUTHORIZED", "API key is revoked")
        return _err("UNAUTHORIZED", "API key is revoked")

    # ---- Load executions
    executions = _load("command_executions.json")
    if not isinstance(executions, list):
        executions = []

    # If the provided id doesn't look like an execution id but matches an api key id, treat it as a client bug:
    # they likely passed their key id in place of execution id (as observed in audit). This must be rejected with a
    # clear validation error rather than a misleading NOT_FOUND.
    if exec_id == api_key_id or exec_id.startswith("term_key_"):
        _append_audit(
            "cancel_command_execution",
            api_key_id,
            "error",
            "VALIDATION_ERROR",
            "id must be a command execution id (term_cmd_...), not an API key id",
            extra={"received_id": exec_id},
        )
        return _err(
            "VALIDATION_ERROR",
            "id must be a command execution id (term_cmd_...), not an API key id",
            received_id=exec_id,
        )

    # Find execution by id
    exec_row = None
    for r in executions:
        if isinstance(r, dict) and r.get("id") == exec_id:
            exec_row = r
            break

    if exec_row is None:
        _append_audit("cancel_command_execution", api_key_id, "error", "NOT_FOUND", "Command execution not found", extra={"id": exec_id})
        return _err("NOT_FOUND", "Command execution not found.", id=exec_id)

    # Enforce ownership
    if exec_row.get("api_key_id") != api_key_id:
        _append_audit("cancel_command_execution", api_key_id, "error", "UNAUTHORIZED", "Execution does not belong to this API key", extra={"id": exec_id})
        return _err("UNAUTHORIZED", "Command execution does not belong to this API key.", id=exec_id)

    # Enforce lifecycle transitions: queued|running -> cancelled only
    cur = exec_row.get("status")
    allowed_from = ("queued", "running")
    if cur not in allowed_from:
        _append_audit(
            "cancel_command_execution",
            api_key_id,
            "error",
            "INVALID_TRANSITION",
            f"Cannot cancel execution from status '{cur}'",
            extra={"id": exec_id, "status": cur},
        )
        return _err("INVALID_TRANSITION", f"Cannot cancel execution from status '{cur}'.", id=exec_id, status=cur)

    # Idempotency: if already cancelled (should not happen due to above), return the row
    # (kept for defensive compatibility)
    if cur == "cancelled":
        _append_audit("cancel_command_execution", api_key_id, "ok", extra={"id": exec_id})
        return {"command_execution": exec_row}

    # Apply mutation
    exec_row["status"] = "cancelled"
    exec_row["updated_at"] = _iso(now)

    # Ensure finished_at is set for terminal states (schema constraint)
    if not exec_row.get("finished_at"):
        exec_row["finished_at"] = _iso(now)

    # Set duration_ms if possible
    started_at = _parse_dt(exec_row.get("started_at"))
    finished_at = _parse_dt(exec_row.get("finished_at")) or now
    if started_at is not None:
        dur = int(max(0, (finished_at - started_at).total_seconds() * 1000))
        exec_row["duration_ms"] = dur
    else:
        if exec_row.get("duration_ms") is None:
            exec_row["duration_ms"] = 0

    # exit_code must be null for cancelled
    exec_row["exit_code"] = None

    # Persist
    _save("command_executions.json", executions)

    # Touch api_keys.last_used_at on successful authenticated operation (best approximation to real dynamics)
    key_row["last_used_at"] = _iso(now)
    key_row["updated_at"] = _iso(now)
    _save("api_keys.json", api_keys)

    _append_audit("cancel_command_execution", api_key_id, "ok", extra={"id": exec_id})

    return {"command_execution": exec_row}

def list_terminal_sessions(api_key, page=None, page_size=None, status=None, host=None, username=None, session=None, last_used_after=None, last_used_before=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0317000" if __import__("os").path.isdir("./environment_mix/0317000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.isoformat().replace("+00:00", "Z")
        return None

    def _parse_rfc3339(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return "TYPE_ERROR"
        ss = s.strip()
        if not ss:
            return "FORMAT_ERROR"
        try:
            if ss.endswith("Z"):
                return datetime.datetime.fromisoformat(ss[:-1] + "+00:00")
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt
        except ValueError:
            return "FORMAT_ERROR"

    # --- Load store
    api_keys = _load("api_keys.json")
    sessions = _load("terminal_sessions.json")
    hosts_rows = _load("hosts.json")
    execs = _load("command_executions.json")
    quotas = _load("usage_quotas.json")
    reqlog = _load("request_logs.json")

    def _log(status_code, credential_id=None, error_code=None):
        latency_ms = int((time.time() - t0) * 1000)
        row = {
            "id": "req_" + str(int(time.time() * 1000)) + "_" + str(os.getpid()),
            "endpoint": "list_terminal_sessions",
            "credential_id": credential_id,
            "status": status_code,
            "error_code": error_code,
            "latency_ms": latency_ms,
            "created_at": _iso(now),
        }
        if isinstance(reqlog, list):
            reqlog.append(row)
            _save("request_logs.json", reqlog)

    # --- Validate inputs
    if not isinstance(api_key, str) or not api_key.strip():
        _log(400, None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")

    if page is None:
        page = 1
    if page_size is None:
        page_size = 50

    if not isinstance(page, int) or page < 1:
        _log(400, None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "page must be an integer >= 1")
    if not isinstance(page_size, int) or page_size < 1 or page_size > 200:
        _log(400, None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "page_size must be an integer between 1 and 200")

    allowed_status = {"active", "expired", "closed", "error"}
    if status is not None:
        if not isinstance(status, str) or status not in allowed_status:
            _log(400, None, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "status must be one of: active, expired, closed, error")

    if host is not None and (not isinstance(host, str) or not host.strip()):
        _log(400, None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "host must be a non-empty string when provided")
    if username is not None and (not isinstance(username, str) or not username.strip()):
        _log(400, None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "username must be a non-empty string when provided")
    if session is not None:
        if not isinstance(session, str) or not session.strip():
            _log(400, None, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "session must be a non-empty string when provided")
        if len(session) < 1 or len(session) > 64:
            _log(400, None, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "session length must be between 1 and 64")

    dt_after = _parse_rfc3339(last_used_after)
    if dt_after in ("TYPE_ERROR", "FORMAT_ERROR"):
        _log(400, None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "last_used_after must be an RFC 3339 timestamp")
    dt_before = _parse_rfc3339(last_used_before)
    if dt_before in ("TYPE_ERROR", "FORMAT_ERROR"):
        _log(400, None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "last_used_before must be an RFC 3339 timestamp")
    if isinstance(dt_after, datetime.datetime) and isinstance(dt_before, datetime.datetime):
        if dt_before < dt_after:
            _log(400, None, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "last_used_before must be >= last_used_after")

    # --- Authenticate (by id or key_prefix; NEVER by key_hash)
    key_row = None
    api_key_norm = api_key.strip()
    for r in api_keys:
        if not isinstance(r, dict):
            continue
        if r.get("id") == api_key_norm or r.get("key_prefix") == api_key_norm:
            key_row = r
            break
    if key_row is None:
        _log(401, None, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Invalid API key")
    if key_row.get("status") != "active":
        _log(401, key_row.get("id"), "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "API key is revoked")

    api_key_id = key_row.get("id")

    # --- Expire any active sessions past expires_at (service dynamics)
    host_by_id = {h.get("id"): h for h in hosts_rows if isinstance(h, dict) and isinstance(h.get("id"), str)}
    changed = False
    for s in sessions:
        if not isinstance(s, dict):
            continue
        if s.get("api_key_id") != api_key_id:
            continue
        if s.get("status") == "active":
            exp_raw = s.get("expires_at")
            exp = _parse_rfc3339(exp_raw) if isinstance(exp_raw, str) else None
            if isinstance(exp, datetime.datetime) and exp <= now:
                s["status"] = "expired"
                s["connection_ref"] = None  # release runtime resource
                s["updated_at"] = _iso(now)
                changed = True
    if changed:
        _save("terminal_sessions.json", sessions)

    # --- Filtering
    def _session_matches(srow):
        if srow.get("api_key_id") != api_key_id:
            return False
        if status is not None and srow.get("status") != status:
            return False
        if session is not None and srow.get("session_name") != session:
            return False

        # host/username filters require looking up host row
        if host is not None or username is not None:
            hrow = host_by_id.get(srow.get("host_id"))
            if not isinstance(hrow, dict):
                return False
            if host is not None:
                if host.strip() == "local":
                    if hrow.get("type") != "local":
                        return False
                else:
                    if hrow.get("type") != "ssh" or hrow.get("host") != host.strip():
                        return False
            if username is not None:
                if hrow.get("type") != "ssh" or hrow.get("username") != username.strip():
                    return False

        # last_used filters
        if dt_after is not None or dt_before is not None:
            lu_raw = srow.get("last_used_at")
            lu = _parse_rfc3339(lu_raw) if isinstance(lu_raw, str) else None
            if not isinstance(lu, datetime.datetime):
                return False
            if isinstance(dt_after, datetime.datetime) and lu < dt_after:
                return False
            if isinstance(dt_before, datetime.datetime) and lu >= dt_before:
                return False

        return True

    filtered = [s for s in sessions if isinstance(s, dict) and _session_matches(s)]

    # sort by last_used_at desc, then created_at desc
    def _key_sort(srow):
        lu = _parse_rfc3339(srow.get("last_used_at")) if isinstance(srow.get("last_used_at"), str) else None
        ca = _parse_rfc3339(srow.get("created_at")) if isinstance(srow.get("created_at"), str) else None
        if not isinstance(lu, datetime.datetime):
            lu = datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        if not isinstance(ca, datetime.datetime):
            ca = datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        return (lu, ca)

    filtered.sort(key=_key_sort, reverse=True)

    total = len(filtered)
    start = (page - 1) * page_size
    end = start + page_size
    items = filtered[start:end]
    has_more = end < total

    # Enrich with host details (non-authoritative, for convenience)
    out_items = []
    for s in items:
        hrow = host_by_id.get(s.get("host_id"))
        out = dict(s)
        if isinstance(hrow, dict):
            out["host"] = {"type": hrow.get("type"), "host": hrow.get("host"), "username": hrow.get("username"), "port": hrow.get("port")}
        out_items.append(out)

    # update last_used_at for credential on successful auth/read
    key_row["last_used_at"] = _iso(now)
    key_row["updated_at"] = _iso(now)
    _save("api_keys.json", api_keys)

    _log(200, api_key_id, None)
    return {
        "data": out_items,
        "meta": {
            "page": page,
            "page_size": page_size,
            "total": total,
            "has_more": has_more,
            "next_page": (page + 1) if has_more else None,
        },
    }

def close_terminal_session(api_key, id, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0317000" if __import__("os").path.isdir("./environment_mix/0317000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.monotonic()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.isoformat().replace("+00:00", "Z")
        return None

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            if v.tzinfo is None:
                return v.replace(tzinfo=datetime.timezone.utc)
            return v
        if isinstance(v, str):
            s = v.strip()
            try:
                if s.endswith("Z"):
                    s = s[:-1] + "+00:00"
                dt = datetime.datetime.fromisoformat(s)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                return dt
            except Exception:
                return None
        return None

    def _gen_id(prefix):
        return f"{prefix}_{int(time.time()*1000)}_{os.urandom(6).hex()}"

    def _audit(api_key_id, status_s, error_code=None, message=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(
            {
                "id": _gen_id("req"),
                "endpoint": "close_terminal_session",
                "api_key_id": api_key_id,
                "status": status_s,
                "error_code": error_code,
                "message": message,
                "timestamp": _iso(now),
                "latency_ms": int((time.monotonic() - t0) * 1000),
            }
        )
        _save("request_logs.json", logs)

    # Validate
    if not isinstance(api_key, str) or not api_key.strip():
        resp = _err("VALIDATION_ERROR", "api_key must be a non-empty string")
        _audit(None, "error", error_code=resp["error"]["code"], message=resp["error"]["message"])
        return resp
    if not isinstance(id, str) or not id.strip():
        resp = _err("VALIDATION_ERROR", "id must be a non-empty string")
        _audit(None, "error", error_code=resp["error"]["code"], message=resp["error"]["message"])
        return resp

    api_key_cred = api_key.strip()
    requested_id = id.strip()

    # Authenticate
    keys = _load("api_keys.json")
    if not isinstance(keys, list):
        keys = []
    key_row = None
    for k in keys:
        if not isinstance(k, dict):
            continue
        if k.get("id") == api_key_cred or k.get("key_prefix") == api_key_cred:
            key_row = k
            break
    if key_row is None:
        resp = _err("UNAUTHORIZED", "Invalid API key")
        _audit(None, "error", error_code=resp["error"]["code"], message=resp["error"]["message"])
        return resp
    api_key_id = key_row.get("id")

    sessions = _load("terminal_sessions.json")
    if not isinstance(sessions, list):
        sessions = []

    idx = None
    for i, s in enumerate(sessions):
        if isinstance(s, dict) and s.get("id") == requested_id:
            idx = i
            break

    if idx is None and requested_id.startswith("term_key_"):
        # caller passed api key id; close most recently used closable session for this key
        candidates = []
        for i, s in enumerate(sessions):
            if not isinstance(s, dict):
                continue
            if s.get("api_key_id") != api_key_id:
                continue
            if s.get("status") in ("active", "expired", "error"):
                candidates.append((i, s))
        if candidates:
            candidates.sort(
                key=lambda t: _parse_dt(t[1].get("last_used_at")) or _parse_dt(t[1].get("updated_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc),
                reverse=True,
            )
            idx = candidates[0][0]

    if idx is None:
        resp = _err("NOT_FOUND", "Terminal session not found")
        _audit(api_key_id, "error", error_code=resp["error"]["code"], message=resp["error"]["message"])
        return resp

    sess = sessions[idx]
    if sess.get("api_key_id") != api_key_id:
        resp = _err("UNAUTHORIZED", "Terminal session does not belong to this API key")
        _audit(api_key_id, "error", error_code=resp["error"]["code"], message=resp["error"]["message"])
        return resp

    # Expire active session if it's past expires_at (business rule)
    if sess.get("status") == "active":
        exp = _parse_dt(sess.get("expires_at"))
        if exp is not None and exp <= now:
            sess["status"] = "expired"
            sess["updated_at"] = _iso(now)

    status = sess.get("status")
    if status == "closed":
        resp = _err("INVALID_TRANSITION", "Terminal session is already closed")
        _audit(api_key_id, "error", error_code=resp["error"]["code"], message=resp["error"]["message"])
        return resp

    if status not in ("active", "expired", "error"):
        resp = _err("INVALID_TRANSITION", f"Cannot close terminal session from status '{status}'")
        _audit(api_key_id, "error", error_code=resp["error"]["code"], message=resp["error"]["message"])
        return resp

    # Close + release runtime resources: drop connection_ref
    sess["status"] = "closed"
    sess["connection_ref"] = None
    sess["updated_at"] = _iso(now)

    sessions[idx] = sess
    _save("terminal_sessions.json", sessions)

    # Update key usage timestamps
    key_row["last_used_at"] = _iso(now)
    key_row["updated_at"] = _iso(now)
    _save("api_keys.json", keys)

    _audit(api_key_id, "ok")
    return {"data": sess}

def get_current_identity(api_key, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0317000" if __import__("os").path.isdir("./environment_mix/0317000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.isoformat().replace("+00:00", "Z")
        return None

    def _parse_rfc3339(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        ss = s.strip()
        if not ss:
            return None
        try:
            if ss.endswith("Z"):
                return datetime.datetime.fromisoformat(ss[:-1] + "+00:00")
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt
        except ValueError:
            return None

    api_keys = _load("api_keys.json")
    quotas = _load("usage_quotas.json")
    execs = _load("command_executions.json")
    reqlog = _load("request_logs.json")

    def _log(status_code, credential_id=None, error_code=None):
        latency_ms = int((time.time() - t0) * 1000)
        row = {
            "id": "req_" + str(int(time.time() * 1000)) + "_" + str(os.getpid()),
            "endpoint": "get_current_identity",
            "credential_id": credential_id,
            "status": status_code,
            "error_code": error_code,
            "latency_ms": latency_ms,
            "created_at": _iso(now),
        }
        if isinstance(reqlog, list):
            reqlog.append(row)
            _save("request_logs.json", reqlog)

    # Validate
    if not isinstance(api_key, str) or not api_key.strip():
        _log(400, None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")

    # Authenticate (by id or key_prefix)
    key_row = None
    api_key_norm = api_key.strip()
    for r in api_keys:
        if not isinstance(r, dict):
            continue
        if r.get("id") == api_key_norm or r.get("key_prefix") == api_key_norm:
            key_row = r
            break
    if key_row is None:
        _log(401, None, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Invalid API key")
    if key_row.get("status") != "active":
        _log(401, key_row.get("id"), "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "API key is revoked")

    api_key_id = key_row.get("id")

    quota_row = None
    for q in quotas:
        if isinstance(q, dict) and q.get("api_key_id") == api_key_id:
            quota_row = q
            break

    # usage counters
    one_min_ago = now - datetime.timedelta(seconds=60)
    running = 0
    accepted_last_min = 0
    for e in execs:
        if not isinstance(e, dict):
            continue
        if e.get("api_key_id") != api_key_id:
            continue
        st = e.get("status")
        if st == "running":
            running += 1
        ca = _parse_rfc3339(e.get("created_at")) if isinstance(e.get("created_at"), str) else None
        if isinstance(ca, datetime.datetime) and ca >= one_min_ago:
            accepted_last_min += 1

    # Update key last_used_at on successful auth
    key_row["last_used_at"] = _iso(now)
    key_row["updated_at"] = _iso(now)
    _save("api_keys.json", api_keys)

    identity = {
        "api_key": {
            "id": key_row.get("id"),
            "key_prefix": key_row.get("key_prefix"),
            "label": key_row.get("label"),
            "status": key_row.get("status"),
            "created_at": key_row.get("created_at"),
            "updated_at": key_row.get("updated_at"),
            "last_used_at": key_row.get("last_used_at"),
        },
        "scopes": ["terminal:read", "terminal:write", "command:execute"],
        "quota": quota_row,
        "usage": {
            "running_executions": running,
            "accepted_executions_last_60s": accepted_last_min,
        },
        "server_time": _iso(now),
    }

    _log(200, api_key_id, None)
    return {"data": identity}
